<?php
$root=dirname(__DIR__,2); $credentialFile=__DIR__.'/credentials.json';
$credentials=is_file($credentialFile) ? json_decode(file_get_contents($credentialFile),true,512,JSON_THROW_ON_ERROR)
    : ['password'=>'PhxDemo!'.bin2hex(random_bytes(6)), 'accounts'=>[
        ['username'=>'demo_admin','full_name'=>'Demo Administrator','role'=>'admin'],
        ['username'=>'demo_cashier1','full_name'=>'Demo Cashier One','role'=>'cashier'],
        ['username'=>'demo_cashier2','full_name'=>'Demo Cashier Two','role'=>'cashier'],
    ]];
if (!isset($credentials['hash'])) $credentials['hash']=password_hash($credentials['password'],PASSWORD_BCRYPT,['cost'=>12]);
file_put_contents($credentialFile,json_encode($credentials,JSON_PRETTY_PRINT|JSON_THROW_ON_ERROR));
$literal=static fn(string $value): string=>"'".str_replace("'","''",$value)."'";
$sql="-- Pharxmaco OPTIONAL demo login accounts, October 15, 2026.\n-- Select the existing database. This is a data seed, not a schema migration.\n-- Creates one administrator and two cashiers; passwords are listed in the companion .md file.\n-- Requires the existing users.session_version field.\n-- Reimport skips existing usernames, including inactive or edited demo accounts.\n-- Does not reset passwords, change permissions, or create sales, shifts, stock or branches.\n-- Demo accounts use normal application permissions and the selected database.\nSELECT id, full_name, username, password, role, branch_id, status, session_version, created_at, updated_at FROM users LIMIT 0;\nSELECT id, branch_name, status FROM branches LIMIT 0;\n\nSTART TRANSACTION;\n-- Prefer the active Main Branch; otherwise use the first active branch.\n-- To choose a specific branch, replace this assignment with its active branch ID.\nSET @phx_demo_branch_id = (SELECT id FROM branches WHERE status = 'active'\n    ORDER BY CASE WHEN branch_name = 'Main Branch' THEN 0 ELSE 1 END, id LIMIT 1);\nSET @phx_demo_created_at = NOW();\n";
foreach ($credentials['accounts'] as $index=>$account) {
    $branch=$account['role']==='cashier'?'@phx_demo_branch_id':'NULL';
    $sql.="\nINSERT INTO users (full_name, username, password, role, branch_id, status, session_version, created_at, updated_at)\nSELECT ".$literal($account['full_name']).', '.$literal($account['username']).', '.$literal($credentials['hash']).', '.$literal($account['role']).', '.$branch.", 'active', REPLACE(UUID(), '-', ''), @phx_demo_created_at, @phx_demo_created_at\nWHERE EXISTS (SELECT 1 FROM branches WHERE id = @phx_demo_branch_id AND status = 'active')\nAND NOT EXISTS (SELECT 1 FROM users WHERE username = ".$literal($account['username']).");\nSET @phx_demo_added_".$index." = ROW_COUNT();\n";
}
$sql.="\nCOMMIT;\nSELECT CASE WHEN @phx_demo_branch_id IS NULL THEN 'No active branch found; no demo accounts created' ELSE 'Demo account import completed; existing usernames preserved' END AS demo_status,\n    @phx_demo_branch_id AS cashier_branch_id,\n    (@phx_demo_added_0 + @phx_demo_added_1 + @phx_demo_added_2) AS accounts_created;\nSELECT u.id, u.full_name, u.username, u.role, u.status, b.branch_name FROM users u\nLEFT JOIN branches b ON b.id = u.branch_id\nWHERE u.username IN ('demo_admin', 'demo_cashier1', 'demo_cashier2') ORDER BY u.username;\nSET @phx_demo_branch_id = NULL, @phx_demo_created_at = NULL,\n    @phx_demo_added_0 = NULL, @phx_demo_added_1 = NULL, @phx_demo_added_2 = NULL;\n";
file_put_contents($root.'/database/upgrades/2026-10-15-demo-users.sql',$sql);
$doc="# Optional demo login accounts\n\nImport `2026-10-15-demo-users.sql` into the existing database in phpMyAdmin. Keep this optional seed separate from the normal schema upgrade. It is also applied to the current local database when prepared by this task.\n\n| Username | Role | Branch |\n|---|---|---|\n| `demo_admin` | Administrator | All branches |\n| `demo_cashier1` | Cashier | Selected active branch |\n| `demo_cashier2` | Cashier | Same branch |\n\n**Password for all three newly created accounts:** `".$credentials['password']."`\n\nThe SQL prefers an active **Main Branch**, then the first active branch. You can edit the branch assignment at the top before importing. If there is no active branch, it creates no accounts and reports that result. The administrator has normal full administrator access; these are normal accounts, not an isolated demo mode. Transactions made with them affect the selected database's sales and stock.\n\nExisting usernames are skipped. Reimport does not reset a password, reactivate an account, change a branch or grant a new role. The listed password applies only to accounts this seed creates.\n\nTo demonstrate the cashier workflow:\n\n1. Sign in as `demo_cashier1`, open **My Day**, select the shared drawer and enter counted opening cash.\n2. Use **Open POS** to make a demo sale. My Day shows that cashier's sales, transaction count and products sold.\n3. Finish the cart, resolve held sales, count and close the shift, then choose **Demo Cashier Two** for handover.\n4. Sign in as `demo_cashier2`, count the handover cash and start the next shift.\n5. Sign in as `demo_admin` and open **Cashier Shifts** to review and print the closing report.\n\nOne shared drawer can have only one active cashier. Existing shifts, handovers and held carts are preserved. This file creates accounts only; it does not fabricate transaction history or open shifts. Deactivate the demo accounts under **Users** when finished, and change their passwords before giving them ongoing access.\n";
$doc=str_replace('Sign in as `demo_cashier1`, open **My Day**, select the shared drawer and enter counted opening cash.', 'Sign in as `demo_cashier1`. On **Start Shift**, select the shared drawer, enter counted opening cash and choose **Start shift and open POS**.', $doc);
file_put_contents($root.'/database/upgrades/2026-10-15-demo-users.md',$doc);
echo 'Prepared three optional demo accounts; credentials are in the companion guide.'.PHP_EOL;
